<?php
namespace App\Http\Controllers;
use App\Models\User; use App\Services\NexarionState; use Illuminate\Http\Request; use Illuminate\Support\Facades\Auth; use Illuminate\Support\Facades\DB; use Illuminate\Support\Facades\Hash; use Illuminate\Support\Facades\RateLimiter;
class AdminController extends Controller {
public function index(NexarionState $state){$auth=Auth::check();$publicSite=$state->publicData()['site']??[];return view('admin',['isAuthenticated'=>$auth,'initialState'=>$auth?$state->adminState(Auth::id()):null,'publicSite'=>$publicSite]);}
public function login(Request $request,NexarionState $state){$v=$request->validate(['username'=>'required|string|max:100','password'=>'required|string|max:255','remember'=>'nullable|boolean']);$key='admin-login:'.$request->ip().':'.strtolower($v['username']);if(RateLimiter::tooManyAttempts($key,5))return response()->json(['ok'=>false,'message'=>'Too many attempts. Try again in '.RateLimiter::availableIn($key).' seconds.'],429);if(!Auth::attempt(['username'=>$v['username'],'password'=>$v['password']],(bool)($v['remember']??false))){RateLimiter::hit($key,30);DB::table('activities')->insert(['type'=>'login_failed','message'=>'Failed login attempt for "'.$v['username'].'"','occurred_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);return response()->json(['ok'=>false,'message'=>'Invalid username or password.'],401);}RateLimiter::clear($key);$request->session()->regenerate();DB::table('activities')->insert(['type'=>'login','message'=>$v['username'].' signed in','occurred_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);return response()->json(['ok'=>true,'state'=>$state->adminState(Auth::id()),'csrf_token'=>csrf_token()]);}
public function logout(Request $request){if(Auth::check())DB::table('activities')->insert(['type'=>'logout','message'=>Auth::user()->username.' signed out','occurred_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);Auth::logout();$request->session()->invalidate();$request->session()->regenerateToken();return response()->json(['ok'=>true]);}
public function state(NexarionState $state){return response()->json(['ok'=>true,'state'=>$state->adminState(Auth::id())]);}
public function saveState(Request $request,NexarionState $state){$payload=$request->validate(['state'=>'required|array'])['state'];$state->saveAdminState($payload);return response()->json(['ok'=>true]);}
public function account(Request $request,NexarionState $state){$v=$request->validate(['username'=>'required|string|min:3|max:100','current_password'=>'required|string','new_password'=>'nullable|string|min:8|confirmed']);$u=$request->user();if(!Hash::check($v['current_password'],$u->password))return response()->json(['ok'=>false,'message'=>'Current password is incorrect.'],422);if(User::where('username',$v['username'])->where('id','!=',$u->id)->exists())return response()->json(['ok'=>false,'message'=>'Username is already in use.'],422);$u->username=$v['username'];if(!empty($v['new_password']))$u->password=$v['new_password'];$u->save();DB::table('activities')->insert(['type'=>'settings','message'=>'Account updated','occurred_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);return response()->json(['ok'=>true,'state'=>$state->adminState($u->id)]);}


public function sendNotice(Request $request){$v=$request->validate(['to'=>'required|array|min:1|max:50','to.*'=>'required|email|max:190','subject'=>'required|string|max:200','body'=>'required|string|max:10000']);foreach(array_unique($v['to']) as $email){\Illuminate\Support\Facades\Mail::raw($v['body'],function($m) use($email,$v){$m->to($email)->subject($v['subject']);});}DB::table('notices')->insert(['uid'=>(string)\Illuminate\Support\Str::uuid(),'subject'=>$v['subject'],'recipient_count'=>count(array_unique($v['to'])),'recipients'=>json_encode(array_values(array_unique($v['to']))),'body'=>$v['body'],'sent_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);DB::table('activities')->insert(['type'=>'mail','message'=>'Client notice sent: '.$v['subject'],'occurred_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);return response()->json(['ok'=>true,'message'=>config('mail.default')==='log'?'Notice processed using the log mailer. Configure SMTP to deliver real email.':'Notice sent.','mailer'=>config('mail.default')]);}
public function uploadPortfolioImage(Request $request){$request->merge(['section'=>'projects']);return $this->uploadContentImage($request);}
public function uploadContentImage(Request $request){$v=$request->validate(['section'=>'required|in:projects,posts,team,site','image'=>'required|image|mimes:jpeg,jpg,png,webp,gif|max:5120']);$file=$request->file('image');$folder=['projects'=>'portfolio','posts'=>'posts','team'=>'team','site'=>'branding'][$v['section']];$dir=public_path('uploads/'.$folder);if(!is_dir($dir))mkdir($dir,0775,true);$name=now()->format('YmdHis').'-'.bin2hex(random_bytes(5)).'.'.$file->extension();$file->move($dir,$name);DB::table('activities')->insert(['type'=>'upload','message'=>($v['section']==='site'?'Website logo':ucfirst($v['section']).' image').' uploaded','occurred_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);return response()->json(['ok'=>true,'url'=>'/uploads/'.$folder.'/'.$name]);}
public function deleteMessage(string $uid){DB::table('messages')->where('uid',$uid)->delete();DB::table('activities')->insert(['type'=>'delete','message'=>'Inbox: message deleted','occurred_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);return response()->json(['ok'=>true]);}
public function reset(NexarionState $state){(new \Database\Seeders\DatabaseSeeder)->run();Auth::loginUsingId(1);return response()->json(['ok'=>true,'state'=>$state->adminState(Auth::id())]);}
}
